class Specification {




  constructor() {
    if (new.target === Specification) {
      throw new TypeError('Cannot construct Specification instances directly - must use a subclass');
    }
  }








  isSatisfiedBy(_entity) {
    throw new Error(`${this.constructor.name} must implement isSatisfiedBy() method`);
  }






  and(other) {
    return new _CompositeSpecificationClass('AND', [this, other]);
  }






  or(other) {
    return new _CompositeSpecificationClass('OR', [this, other]);
  }





  not() {
    return new _CompositeSpecificationClass('NOT', [this]);
  }







  toQuery(_queryBuilder) {
    throw new Error(`${this.constructor.name} cannot be translated to a database query`);
  }
















  toQueryObject() {
    return null;
  }





  canBeTranslatedToQuery(queryObjectCriteria = this.toQueryObject()) {
    if (queryObjectCriteria !== null && queryObjectCriteria !== undefined) {
      return true;
    }
    if (this.toQuery === Specification.prototype.toQuery) {
      return false;
    }
    try {
      const mockBuilder = {
        where: () => mockBuilder,
        andWhere: () => mockBuilder,
        orWhere: () => mockBuilder,
        whereLike: () => mockBuilder,
        whereIn: () => mockBuilder
      };
      this.toQuery(mockBuilder);
      return true;
    } catch (_error) {
      return false;
    }
  }





  toString() {
    return `${this.constructor.name}()`;
  }
}
;







class EqualityFieldSpec extends Specification {





  constructor(column, read, expected) {
    super();
    this._column = column;
    this._read = read;
    this._expected = expected;
  }
  isSatisfiedBy(entity) {
    return this._read(entity) === this._expected;
  }
  toQueryObject() {
    return {
      [this._column]: this._expected
    };
  }
  toString() {
    return `${this._column} = ${String(this._expected)}`;
  }
}
