class CompositeSpecification extends Specification {






  constructor(operator, specifications) {
    super();
    this.operator = operator.toUpperCase();
    this.specifications = specifications;
    this._validateOperator();
    this._validateSpecifications();
  }






  _validateOperator() {
    const validOperators = ['AND', 'OR', 'NOT'];
    if (!validOperators.includes(this.operator)) {
      throw new SpecificationException(`Invalid operator: ${this.operator}. Valid operators: ${validOperators.join(', ')}`, 'CompositeSpecification');
    }
  }






  _validateSpecifications() {
    if (!Array.isArray(this.specifications) || this.specifications.length === 0) {
      throw new SpecificationException('specifications must be a non-empty array', 'CompositeSpecification');
    }
    for (const spec of this.specifications) {
      if (!(spec instanceof Specification)) {
        throw new SpecificationException('All items must be Specification instances', 'CompositeSpecification');
      }
    }
  }







  isSatisfiedBy(entity) {
    switch (this.operator) {
      case 'AND':
        return this.specifications.every(spec => spec.isSatisfiedBy(entity));
      case 'OR':
        return this.specifications.some(spec => spec.isSatisfiedBy(entity));
      case 'NOT':
        if (this.specifications.length !== 1) {
          throw new SpecificationException('NOT operator requires exactly one specification', 'CompositeSpecification');
        }
        return !this.specifications[0].isSatisfiedBy(entity);
      default:
        return false;
    }
  }







  toQuery(queryBuilder) {
    if (this.operator === 'NOT') {
      throw new SpecificationException('NOT operator cannot be translated to SheetDBLib queries', 'CompositeSpecification');
    }


    for (const spec of this.specifications) {
      if (!spec.canBeTranslatedToQuery()) {
        throw new SpecificationException('Cannot translate composite specification - one or more child specifications cannot be translated', 'CompositeSpecification');
      }
    }


    let builder = this.specifications[0].toQuery(queryBuilder);


    for (let i = 1; i < this.specifications.length; i++) {
      const spec = this.specifications[i];


      const tempBuilder = {
        _whereClauses: [],
        where(field, operator, value) {
          this._whereClauses.push({
            field,
            operator,
            value
          });
          return this;
        },
        andWhere(field, operator, value) {
          this._whereClauses.push({
            field,
            operator,
            value
          });
          return this;
        },
        orWhere(field, operator, value) {
          this._whereClauses.push({
            field,
            operator,
            value
          });
          return this;
        },
        whereLike(field, pattern) {
          this._whereClauses.push({
            field,
            operator: 'LIKE',
            value: pattern
          });
          return this;
        },
        whereIn(field, values) {
          this._whereClauses.push({
            field,
            operator: 'IN',
            value: values
          });
          return this;
        }
      };
      spec.toQuery(tempBuilder);


      for (const clause of tempBuilder._whereClauses) {
        if (clause.operator === 'IN') {
          if (this.operator === 'AND') {

            builder = builder.andWhere(clause.field, 'IN', clause.value);
          } else {
            builder = builder.orWhere(clause.field, 'IN', clause.value);
          }
        } else if (clause.operator === 'LIKE') {

          if (this.operator === 'AND') {
            builder = builder.andWhere(clause.field, 'LIKE', clause.value);
          } else {
            builder = builder.orWhere(clause.field, 'LIKE', clause.value);
          }
        } else {
          if (this.operator === 'AND') {
            builder = builder.andWhere(clause.field, clause.operator, clause.value);
          } else {
            builder = builder.orWhere(clause.field, clause.operator, clause.value);
          }
        }
      }
    }
    return builder;
  }





  canBeTranslatedToQuery() {
    if (this.operator === 'NOT') {
      return false;
    }
    return this.specifications.every(spec => spec.canBeTranslatedToQuery());
  }





  toString() {
    if (this.operator === 'NOT') {
      return `NOT (${this.specifications[0].toString()})`;
    }
    return `(${this.specifications.map(s => s.toString()).join(` ${this.operator} `)})`;
  }
}


_registerCompositeSpecification(CompositeSpecification);
;










class FieldSpecification extends Specification {








  constructor(field, operator, value, secondValue = null) {
    super();
    this._field = field;
    this._operator = operator;


    if (operator === 'between' && Array.isArray(value) && value.length === 2) {
      this._value = value[0];
      this._secondValue = value[1];
    } else {
      this._value = value;
      this._secondValue = secondValue;
    }
    this._validateOperator();
  }






  _validateOperator() {
    const validOperators = ['equals', 'notEquals', 'greaterThan', 'lessThan', 'greaterThanOrEqual', 'lessThanOrEqual', 'in', 'notIn', 'between', 'like', 'notLike'];
    if (!validOperators.includes(this._operator)) {
      throw new SpecificationException(`Invalid operator: ${this._operator}. Valid operators: ${validOperators.join(', ')}`, 'FieldSpecification');
    }


  }







  _getFieldValue(entity) {
    if (!entity) {
      return undefined;
    }


    const parts = this._field.split('.');
    let value = entity;
    for (const part of parts) {
      if (value && typeof value === 'object') {
        value = value[part];
      } else {
        return undefined;
      }
    }
    return value;
  }









  isSatisfiedBy(entity) {

    if (entity === null || entity === undefined) {
      throw new SpecificationException('Cannot evaluate specification on null or undefined entity', 'FieldSpecification');
    }
    const fieldValue = this._getFieldValue(entity);
    switch (this._operator) {
      case 'equals':
        return fieldValue === this._value;
      case 'notEquals':
        return fieldValue !== this._value;
      case 'greaterThan':
        return fieldValue > this._value;
      case 'lessThan':
        return fieldValue < this._value;
      case 'greaterThanOrEqual':
        return fieldValue >= this._value;
      case 'lessThanOrEqual':
        return fieldValue <= this._value;
      case 'in':

        if (!Array.isArray(this._value)) {
          throw new SpecificationException('in operator requires value to be an array', 'FieldSpecification');
        }
        return this._value.includes(fieldValue);
      case 'notIn':

        if (!Array.isArray(this._value)) {
          throw new SpecificationException('notIn operator requires value to be an array', 'FieldSpecification');
        }
        return !this._value.includes(fieldValue);
      case 'between':


        if (Array.isArray(this._value) && this._value.length !== 2) {
          throw new SpecificationException('between operator requires an array of exactly 2 values', 'FieldSpecification');
        }

        if (this._secondValue === null || this._secondValue === undefined) {
          throw new SpecificationException('between operator requires a second value', 'FieldSpecification');
        }
        return fieldValue >= this._value && fieldValue <= this._secondValue;
      case 'like':
        {
          if (typeof fieldValue !== 'string' || typeof this._value !== 'string') {
            return false;
          }


          let pattern = RegexUtils.escape(this._value).replace(/%/g, '.*');

          pattern = '^' + pattern + '$';
          const regex = new RegExp(pattern, 'i');
          return regex.test(fieldValue);
        }
      case 'notLike':
        {
          if (typeof fieldValue !== 'string' || typeof this._value !== 'string') {
            return true; 
          }

          let notLikePattern = RegexUtils.escape(this._value).replace(/%/g, '.*');
          notLikePattern = '^' + notLikePattern + '$';
          const notLikeRegex = new RegExp(notLikePattern, 'i');
          return !notLikeRegex.test(fieldValue);
        }
      default:
        return false;
    }
  }





  toQueryObject() {
    return this._operator === 'equals' ? {
      [this._field]: this._value
    } : null;
  }







  toQuery(queryBuilder) {
    switch (this._operator) {
      case 'equals':
        return queryBuilder.where(this._field, '=', this._value);
      case 'notEquals':
        return queryBuilder.where(this._field, '!=', this._value);
      case 'greaterThan':
        return queryBuilder.where(this._field, '>', this._value);
      case 'lessThan':
        return queryBuilder.where(this._field, '<', this._value);
      case 'greaterThanOrEqual':
        return queryBuilder.where(this._field, '>=', this._value);
      case 'lessThanOrEqual':
        return queryBuilder.where(this._field, '<=', this._value);
      case 'in':
        return queryBuilder.whereIn(this._field, this._value);
      case 'notIn':

        throw new SpecificationException(`Operator 'notIn' cannot be translated to database query - use in-memory filtering`, 'FieldSpecification');
      case 'between':

        return queryBuilder.where(this._field, '>=', this._value).andWhere(this._field, '<=', this._secondValue);
      case 'like':
        return queryBuilder.whereLike(this._field, this._value);
      case 'notLike':

        throw new SpecificationException(`Operator 'notLike' cannot be translated to database query - use in-memory filtering`, 'FieldSpecification');
      default:
        throw new SpecificationException(`Cannot translate operator ${this._operator} to query`, 'FieldSpecification');
    }
  }





  toString() {
    if (this._operator === 'between') {
      return `${this._field} ${this._operator} ${this._value} and ${this._secondValue}`;
    }
    return `${this._field} ${this._operator} ${this._value}`;
  }
}
;









class FunctionSpecification extends Specification {






  constructor(predicateFunction, description = null) {
    super();
    if (typeof predicateFunction !== 'function') {
      throw new SpecificationException('predicateFunction must be a function', 'FunctionSpecification');
    }
    this.predicateFunction = predicateFunction;
    this.description = description;
  }







  isSatisfiedBy(entity) {
    try {
      return Boolean(this.predicateFunction(entity));
    } catch (error) {
      throw new SpecificationException(`Failed to evaluate function specification: ${error.message}`, 'FunctionSpecification', {
        error: error.message
      });
    }
  }





  toQuery(_queryBuilder) {
    throw new SpecificationException('Function specifications cannot be translated to database queries', 'FunctionSpecification');
  }





  canBeTranslatedToQuery() {
    return false;
  }





  toString() {
    return this.description ? `Function(${this.description})` : 'Function(custom predicate)';
  }
}
;










function assertSpecificationContract(spec, rows, hydrate) {
  const criteria = spec.toQueryObject();
  if (criteria === null) {
    return {
      ok: true,
      divergenti: []
    };
  }
  const divergenti = rows.filter(row => {
    const viaQuery = Object.entries(criteria).every(([column, value]) => row[column] === value);
    const viaMemory = spec.isSatisfiedBy(hydrate(row));
    return viaQuery !== viaMemory;
  });
  return {
    ok: divergenti.length === 0,
    divergenti
  };
}
;







class InvariantViolationException extends DomainException {





  constructor(aggregateType, violations = []) {
    const message = violations.length > 0 ? `invariant violation in ${aggregateType}: ${violations.join(', ')}` : `invariant violation in ${aggregateType}`;
    super(message, 'Aggregate', {
      aggregateType,
      violations
    });
    this.name = 'InvariantViolationException';
    this.aggregateType = aggregateType;
    this.violations = violations;
  }





  getAggregateType() {
    return this.aggregateType;
  }





  getViolations() {
    return this.violations;
  }





  hasViolations() {
    return this.violations && this.violations.length > 0;
  }
}
;












































