class EnhancedTestRunner {
  constructor() {
    this.registry = [];
    this.results = {
      passed: 0,
      failed: 0,
      skipped: 0,
      errors: []
    };
  }









  register(path, fn, options = {}) {
    this.registry.push({
      path: path,
      fn: fn,
      skip: options.skip || false
    });
    return this;
  }






  run(filter = null) {
    const testsToRun = this.registry.filter(test => {
      if (!filter) return true;
      if (typeof filter === 'string') return test.path.includes(filter);
      if (filter instanceof RegExp) return filter.test(test.path);
      return true;
    });
    this._log(`Running ${testsToRun.length} tests matching filter: ${filter || 'NONE'}`);
    try {
      for (const test of testsToRun) {
        if (test.skip) {
          this._log(`[TEST:SKIP] ${test.path}`);
          this.results.skipped++;
          continue;
        }
        this._runTest(test);
      }
    } catch (error) {
      this._log(`[FATAL:ERROR] ${error.message}`);
      this._log(`[ERROR:STACK] ${error.stack}`);
    }
    this._printSummary();
    return this.results;
  }






  _runTest(test) {
    this._log(`[TEST:START] ${test.path}`);
    const startTime = new Date().getTime();
    try {

      test.fn();
      const duration = new Date().getTime() - startTime;
      this._log(`[TEST:END] PASS | Duration: ${duration}ms`);
      this.results.passed++;
    } catch (rawError) {


      const error = rawError instanceof Error ? rawError : new Error(String(rawError));
      const duration = new Date().getTime() - startTime;
      this._log(`[ERROR:STACK] ${error.stack}`);
      this._log(`[TEST:END] FAIL | Duration: ${duration}ms`);
      this.results.failed++;
      this.results.errors.push({
        path: test.path,
        message: error.message,
        stack: error.stack
      });
    }
  }






  _log(message) {
    if (typeof Logger !== 'undefined') {
      Logger.log(message);
    } else {
      console.log(message);
    }
  }





  _printSummary() {
    this._log('═══════════════════════════════════════════════');
    this._log('TEST EXECUTION SUMMARY');
    this._log(`TOTAL: ${this.results.passed + this.results.failed + this.results.skipped}`);
    this._log(`PASSED: ${this.results.passed}`);
    this._log(`FAILED: ${this.results.failed}`);
    this._log(`SKIPPED: ${this.results.skipped}`);
    this._log('═══════════════════════════════════════════════');
    if (this.results.failed > 0) {
      this._log('FAILED TESTS:');
      for (const err of this.results.errors) {
        this._log(`- ${err.path}: ${err.message}`);
      }
    }
  }
}


const runner = new EnhancedTestRunner();
;




class SmartAssert {









  static _safeStringify(value) {
    if (value === undefined) return 'undefined';
    try {
      return JSON.stringify(value);
    } catch (_e) {
      const seen = new WeakSet();
      try {
        return JSON.stringify(value, (_k, v) => {
          if (v && typeof v === 'object') {
            if (seen.has(v)) return '[Circular]';
            seen.add(v);
          }
          return v;
        });
      } catch (_e2) {
        try {
          return String(value);
        } catch (_e3) {
          return '[Unserializable]';
        }
      }
    }
  }
  static _log(passed, expected, actual, message) {
    const status = passed ? 'PASS' : 'FAIL';
    const expectedStr = this._safeStringify(expected);
    const actualStr = this._safeStringify(actual);
    const logMessage = `[ASSERT:${status}] Expected: ${expectedStr} | Actual: ${actualStr} | Desc: ${message}`;
    if (typeof Logger !== 'undefined') {
      Logger.log(logMessage);
    } else {
      console.log(logMessage);
    }
    if (!passed) {
      throw new Error(logMessage);
    }
  }







  static equals(actual, expected, message = 'Values should be equal') {
    const passed = actual === expected;
    this._log(passed, expected, actual, message);
  }







  static greaterThan(actual, expected, message = 'Actual should be greater than expected') {
    const passed = actual > expected;
    this._log(passed, `> ${expected}`, actual, message);
  }







  static lessThan(actual, expected, message = 'Actual should be less than expected') {
    const passed = actual < expected;
    this._log(passed, `< ${expected}`, actual, message);
  }







  static notEquals(actual, expected, message = 'Values should not be equal') {
    const passed = actual !== expected;
    this._log(passed, expected, actual, message);
  }






  static isTrue(actual, message = 'Value should be true') {
    const passed = !!actual;
    this._log(passed, true, actual, message);
  }






  static isFalse(actual, message = 'Value should be false') {
    const passed = !actual;
    this._log(passed, false, actual, message);
  }






  static isNull(actual, message = 'Value should be null or undefined') {
    const passed = actual === null || actual === undefined;
    this._log(passed, null, actual, message);
  }






  static notNull(actual, message = 'Value should not be null or undefined') {
    const passed = actual !== null && actual !== undefined;
    this._log(passed, 'not null/undefined', actual, message);
  }







  static deepEquals(actual, expected, message = 'Objects should be deeply equal') {
    const actualStr = JSON.stringify(actual);
    const expectedStr = JSON.stringify(expected);
    const passed = actualStr === expectedStr;
    this._log(passed, expected, actual, message);
  }







  static isType(actual, expectedType, message = `Value should be of type ${expectedType}`) {
    const actualType = typeof actual;
    const passed = actualType === expectedType;
    this._log(passed, expectedType, actualType, message);
  }






  static isNumber(actual, message = 'Value should be a number') {
    const passed = typeof actual === 'number' && !isNaN(actual);
    this._log(passed, 'number', typeof actual, message);
  }






  static isString(actual, message = 'Value should be a string') {
    const passed = typeof actual === 'string';
    this._log(passed, 'string', typeof actual, message);
  }







  static contains(array, value, message = 'Array should contain value') {
    const passed = Array.isArray(array) && array.indexOf(value) !== -1;
    this._log(passed, `Array containing ${JSON.stringify(value)}`, array, message);
  }





  static fail(message = 'Intentional failure') {
    this._log(false, 'N/A', 'N/A', message);
  }






  static throws(fn, message = 'Function should throw an error') {
    let caught = false;
    let errorActual = 'No error thrown';
    try {
      fn();
    } catch (e) {
      caught = true;
      errorActual = e.message;
    }
    this._log(caught, 'Error thrown', errorActual, message);
  }
}
;













class SampleSpreadsheetBuilder {



  constructor(spreadsheet) {
    this.spreadsheet = spreadsheet;
    this.id = spreadsheet.getId();
    this.defaultSheet = spreadsheet.getSheets()[0] || null;

    this._headersBySheet = new Map();
  }











  addSheet(name, headerRow) {
    const sheet = this.spreadsheet.insertSheet(name);
    if (headerRow.length > 0) {
      sheet.getRange(1, 1, 1, headerRow.length).setValues([headerRow]);
    }
    this._headersBySheet.set(name, headerRow);
    if (this.defaultSheet !== null) {
      this.spreadsheet.deleteSheet(this.defaultSheet);
      this.defaultSheet = null;
    }
    SpreadsheetApp.flush();
  }











  appendRow(sheetName, row) {
    const sheet = this.spreadsheet.getSheetByName(sheetName);
    if (sheet === null) {
      throw new Error(`Sheet "${sheetName}" not found in spreadsheet "${this.spreadsheet.getName()}".`);
    }
    const headerRow = this._headersBySheet.get(sheetName) || [];
    const values = headerRow.map(header => row[String(header)] !== undefined ? row[String(header)] : '');
    sheet.appendRow(values);
    SpreadsheetApp.flush();
  }









  appendRows(sheetName, rows) {
    if (rows.length === 0) return;
    const sheet = this.spreadsheet.getSheetByName(sheetName);
    if (sheet === null) {
      throw new Error(`Sheet "${sheetName}" not found in spreadsheet "${this.spreadsheet.getName()}".`);
    }
    const headerRow = this._headersBySheet.get(sheetName) || [];
    const values = rows.map(row => headerRow.map(header => row[String(header)] !== undefined ? row[String(header)] : ''));
    sheet.getRange(sheet.getLastRow() + 1, 1, values.length, headerRow.length).setValues(values);
    SpreadsheetApp.flush();
  }





  getUrl() {
    return this.spreadsheet.getUrl();
  }
}
;






class TestContext {
  constructor() {
    this.TEST_ROOT_NAME = 'GAS_TEST_ROOT_PERSISTENT';
    this.TEST_SS_NAME = 'GAS_TEST_SS_PERSISTENT';
    this.TEST_DOC_NAME = 'GAS_TEST_DOC_PERSISTENT';
    this._rootFolder = null;
    this._spreadsheet = null;
    this._document = null;
  }





  getRootFolder() {
    if (this._rootFolder) {
      return this._rootFolder;
    }
    this._rootFolder = this.getOrCreateNamedFolder(this.TEST_ROOT_NAME);
    return this._rootFolder;
  }









  getOrCreateNamedFolder(name, parentFolder = null) {
    const folders = parentFolder ? parentFolder.getFoldersByName(name) : DriveApp.getFoldersByName(name);
    if (folders.hasNext()) {
      return folders.next();
    }
    return parentFolder ? parentFolder.createFolder(name) : DriveApp.createFolder(name);
  }





  getSpreadsheet() {
    if (this._spreadsheet) {
      return this._spreadsheet;
    }
    this._spreadsheet = this.getOrCreateNamedSpreadsheet(this.TEST_SS_NAME, this.getRootFolder());
    return this._spreadsheet;
  }











  getOrCreateNamedSpreadsheet(name, parentFolder = null) {
    const files = parentFolder ? parentFolder.getFilesByName(name) : DriveApp.getFilesByName(name);
    if (files.hasNext()) {
      return SpreadsheetApp.openById(files.next().getId());
    }
    const spreadsheet = SpreadsheetApp.create(name);
    if (parentFolder) {
      const file = DriveApp.getFileById(spreadsheet.getId());
      file.moveTo(parentFolder);
    }
    return spreadsheet;
  }





  getDocument() {
    if (this._document) {
      try {
        this._document.getBody();
        return this._document;
      } catch (_e) {

        this._document = DocumentApp.openById(this._document.getId());
        return this._document;
      }
    }
    const files = DriveApp.getFilesByName(this.TEST_DOC_NAME);
    if (files.hasNext()) {
      const file = files.next();
      this._document = DocumentApp.openById(file.getId());
    } else {
      this._document = DocumentApp.create(this.TEST_DOC_NAME);
      const file = DriveApp.getFileById(this._document.getId());
      file.moveTo(this.getRootFolder());
    }
    return this._document;
  }





  resetSpreadsheet(ss) {
    const targetSs = ss || this.getSpreadsheet();


    const protections = targetSs.getProtections(SpreadsheetApp.ProtectionType.RANGE);
    protections.forEach(p => {
      p.remove();
    });


    targetSs.getSheets().forEach(sheet => {
      sheet.getProtections(SpreadsheetApp.ProtectionType.SHEET).forEach(p => {
        p.remove();
      });
    });


    const namedRanges = targetSs.getNamedRanges();
    namedRanges.forEach(nr => {
      nr.remove();
    });
    const sheets = targetSs.getSheets();


    if (sheets.length === 0) {
      targetSs.insertSheet('Sheet1');
    } else {
      const firstSheet = sheets[0];
      firstSheet.setName('TEMP_RESET_' + new Date().getTime());
      firstSheet.clear().clearContents().clearFormats().clearNotes();


      for (let i = 1; i < sheets.length; i++) {
        targetSs.deleteSheet(sheets[i]);
      }
      firstSheet.setName('Sheet1');
    }
  }









  buildSampleSpreadsheet(name, parentFolder = null) {
    const spreadsheet = this.getOrCreateNamedSpreadsheet(name, parentFolder);
    this.resetSpreadsheet(spreadsheet);
    return new SampleSpreadsheetBuilder(spreadsheet);
  }







  buildSampleSpreadsheetById(spreadsheetId) {
    const spreadsheet = SpreadsheetApp.openById(spreadsheetId);
    this.resetSpreadsheet(spreadsheet);
    return new SampleSpreadsheetBuilder(spreadsheet);
  }




  resetDocument() {
    const doc = this.getDocument();
    try {
      this._clearBodySafely(doc.getBody());
    } catch (_e) {

      this._document = DocumentApp.openById(doc.getId());
      this._clearBodySafely(this._document.getBody());
    }
  }











  _clearBodySafely(body) {
    try {
      body.clear();
    } catch (e) {
      if (!/last paragraph/.test(e.message)) {
        throw e;
      }
      body.appendParagraph('');
      body.clear();
    }
  }




  resetAll() {
    this.resetSpreadsheet();
    this.resetDocument();
    this._log('TestContext reset completed.');
  }






  _log(message) {
    if (typeof Logger !== 'undefined') {
      Logger.log(message);
    } else {
      console.log(message);
    }
  }
}


